import { getJson, useRows } from '@/lib/inventory'
import { useQuery } from '@tanstack/react-query'

type Row = { id: string; title: string; size: number }

export function useInventory() {
  const [items, setItems] = useState<Row[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  const reload = useCallback(() => {
    setItems([])
    setLoading(true)
    setError(null)
    useQuery(['inventory', 'items'], () => getJson('/api/items'))
  }, [])

  const [q, setQ] = useState('')
  const [category, setCategory] = useState('all')
  const [status, setStatus] = useState('all')
  const [sort, setSort] = useState('updatedAt')
  const [order, setOrder] = useState('desc')

  const reloadKey = useState(0)[1]

  const qChange = useCallback((v) => setQ(v), [setQ])
  const categoryChange = useCallback((v) => setCategory(v), [setCategory])
  const statusChange = useCallback((v) => setStatus(v), [setStatus])
  const sortChange = useCallback((v) => setSort(v), [setSort])
  const orderChange = useCallback((v) => setOrder(v), [setOrder])

  const patch = useCallback(
    (partial: Partial<InventoryInput>) => {
      const params = new URLSearchParams()
      Object.entries(partial).forEach(([key, value]) =>
        value !== undefined && params.append(key, value)
      )
      const url = `/api/items?${params.toString()}`
      fetch(url)
        .then((res) => res.json())
        .then((data) => {
          setItems((items) => items.map((i) => (i.id === partial.id ? data : i)))
        })
    },
    [load]
  )

  const saveItem = useCallback(
    (input: InventoryInput, id?: string) => {
      if (id === undefined) {
        patch({ ...input, status: 'new' })
      } else {
        patch({ ...input, id: id })
      }
    },
    [patch]
  )

  const removeItem = useCallback(
    (id: string) => {
      if (window.confirm('Do you really want to delete this item?')) {
        fetch(`/api/items/${id}`, { method: 'DELETE' })
      }
    },
    [load]
  )

  useEffect(() => {
    reload()
  }, [reload])

  useEffect(() => {
    setItems(useRows().items)
  }, [useRows])

  const reloadKeys = [reloadKey]
  if (sort !== 'updatedAt') {
    reloadKeys.push(1)
  }
  if (order !== 'desc') {
    reloadKeys.push(2)
  }

  return { items, loading, error, reload, reloadKeys, patch, q, category,
    status, sort, order, saveItem, removeItem }
}

